sys_script_include.script:
var convertFilestoPDF = Class.create();
convertFilestoPDF.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    convertHTMLtoPDF: function() {
        var rest = new sn_ws.RESTMessageV2();
        rest.setEndpoint('https://api.eu.apyhub.com/chisleroff/pdf-from-html');
        rest.setHttpMethod('POST');
        rest.setRequestHeader('Content-Type', 'application/json');
        rest.setRequestHeader('Accept', 'application/json');
        rest.setRequestHeader('apy-token', 'bc0ca28e0045abb1ad5b486b70c212c1eebed734182127618d3f478a631b6fc1');
        rest.setRequestBody('{"html":"<html><body><h1>Hello, world!</h1></body></html>"}');
        rest.setSaveResponseBodyAsAttachment(true);


        // 4. Define the target record where the PDF will be attached
        var targetTable = 'incident'; // Replace with your target table name
        var targetSysId = 'a83820b58f723300e7e16c7827bdeed2'; // Replace with your actual record SysID
        var fileName = 'GeneratedDocument.pdf';
        var contentType = 'application/pdf';

        // rest.setAttachmentTarget(targetTable, targetSysId);
        // rest.setAttachmentFilename(fileName);

        // 5. Execute the HTTP Request
        var response = rest.execute();
        var statusCode = response.getStatusCode();
        var httpStatus = response.getStatusCode();

        gs.info("--- REST API Call Results ---");
        gs.info("HTTP Status Code: " + httpStatus);

        if (httpStatus == 200) {
            // 3. Query the actual record object
            var grIncident = new GlideRecord(targetTable);
            if (grIncident.get(targetSysId)) {

                // 4. Extract response data and attach manually
                var responseBody = response.getBody();
                var attachment = new sn_ws.GlideSysAttachment();

                // If the API returns raw binary text or base64 stream, write it directly
                attachment.write(grIncident, fileName, 'application/pdf', responseBody);

                gs.info("Success: File attached to incident " + grIncident.getValue('number'));
            } else {
                gs.error("Error: Incident record with sys_id " + targetSysId + " was not found.");
            }
        } else {
            gs.error("API Call Failed with status: " + httpStatus);
        }



    },


    convertHTMLtoPDFInternal: function() {

        // 4. Define the target record where the PDF will be attached
        var targetSysId = 'a83820b58f723300e7e16c7827bdeed2'; // Replace with your actual record SysID
        var fileName = 'GeneratedDocument.pdf';
        var contentType = 'application/pdf';
        var targetTable = 'incident';
        var pdfName = 'InternalGeneratedDoc.pdf';

        // 1. Define your HTML template string
        var htmlContent = "<html><body>" +
            "<h1 style='color: #032d5b;'>Incident Report</h1>" +
            "<p>Generated natively inside ServiceNow without an external API!</p>" +
            "<table border='1' style='width:100%; border-collapse: collapse;'>" +
            "<tr><th style='padding:8px;'>Field</th><th style='padding:8px;'>Details</th></tr>" +
            "<tr><td style='padding:8px;'>Source</td><td style='padding:8px;'>Internal PDF Generation Engine</td></tr>" +
            "</table>" +
            "</body></html>";



        // 3. Call ServiceNow's native PDF Engine
        var pdfAPI = new sn_pdfgeneratorutils.PDFGenerationAPI();
        var result = pdfAPI.convertToPDF(htmlContent, targetTable, targetSysId, pdfName);

        // 4. Log the result
        gs.info("PDF Generation Status: " + JSON.stringify(result));

    },



    convertHTMLtoPdfwithStyle: function() {

        // ==========================================
        // 1. CONFIGURATION & TARGET RECORD SETUP
        // ==========================================
        var targetSysId = 'a83820b58f723300e7e16c7827bdeed2';
        var targetTable = 'incident';
        var pdfName = 'FormattedIncidentReportFormatted.pdf';

        // ==========================================
        // 2. DEFINE SEPARATE PRINT CSS STYLES
        // ==========================================
        var customStyles = "<style>" +
            // Global Document & Page Layout (Margins, Headers, Footers)
            "@page {" +
            "size: A4 portrait;" +
            "margin-top: 1.5in;" +
            "margin-bottom: 1.5in;" +
            "margin-left: 1in;" +
            "margin-right: 1in;" +

            // Running Document Header
            "@top-center {" +
            "content: 'INTERNAL INCIDENT REPORT';" +
            "font-family: sans-serif;" +
            "font-size: 9pt;" +
            "color: #777777;" +
            "border-bottom: 1px solid #ddd;" +
            "}" +

            // Dynamic Footer: Page Numbers
            "@bottom-right {" +
            "content: 'Page ' counter(page) ' of ' counter(pages);" +
            "font-family: sans-serif;" +
            "font-size: 10pt;" +
            "color: #555555;" +
            "}" +

            // Dynamic Footer: Classification
            "@bottom-left {" +
            "content: 'Confidential Document';" +
            "font-family: sans-serif;" +
            "font-size: 10pt;" +
            "color: #999999;" +
            "}" +
            "}" +

            // Core Text Typography Customization
            "body {" +
            "font-family: sans-serif;" + // Uses system fallback to prevent platform bugs
            "font-size: 11pt;" + // Base text size
            "line-height: 1.6;" +
            "color: #333333;" +
            "}" +
            "h1 {" +
            "color: #032d5b;" +
            "font-size: 22pt;" + // Custom H1 text size
            "margin-bottom: 15px;" +
            "}" +
            "h2 {" +
            "color: #032d5b;" +
            "font-size: 16pt;" + // Custom H2 text size
            "}" +

            // Table Structure Layouts
            "table {" +
            "width: 100%;" +
            "border-collapse: collapse;" +
            "margin-top: 15px;" +
            "margin-bottom: 15px;" +
            "}" +
            "th {" +
            "background-color: #032d5b;" +
            "color: #ffffff;" +
            "padding: 10px;" +
            "text-align: left;" +
            "font-size: 11pt;" +
            "}" +
            "td {" +
            "padding: 10px;" +
            "border: 1px solid #cccccc;" +
            "font-size: 10pt;" +
            "}" +
            "</style>";

        // ==========================================
        // 3. YOUR CUSTOM HTML CONTENT (From Incident)
        // ==========================================
        // You can replace this string variable with your incoming incident payload string.
        // Ensure your content doesn't contain a duplicate <html> or <head> tag block to avoid conflicts.
        var customIncidentHtmlContent = "<h1>Incident Summary</h1>" +
            "<p>This area accepts any custom HTML string generated dynamically from your incident processing blocks.</p>" +
            "<table>" +
            "<tr><th>Incident Field</th><th>Value</th></tr>" +
            "<tr><td>Short Description</td><td>Network outage in primary datacenter</td></tr>" +
            "<tr><td>Priority</td><td>1 - Critical</td></tr>" +
            "</table>";

        // ==========================================
        // 4. COMBINE AND CONVERT
        // ==========================================
        // Assembles the final cleanly structured HTML envelope for the rendering engine
        var finalHtmlDocument = "<html>" +
            "<head>" + customStyles + "</head>" +
            "<body>" + customIncidentHtmlContent + "</body>" +
            "</html>";

        // Execute native engine stream
        var pdfAPI = new sn_pdfgeneratorutils.PDFGenerationAPI();
        var result = pdfAPI.convertToPDF(finalHtmlDocument, targetTable, targetSysId, pdfName);

        gs.info("PDF Generation Status: " + JSON.stringify(result));




    },





    type: 'convertFilestoPDF'
});
